data.query:
query Query($where: MaintenanceChecklistResultWhereInput, $orderBy: [MaintenanceChecklistResultOrderByInput!], $first: Int, $after: String) {
  maintenanceChecklistResult(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        result
        maintenanceChecklistTaskId
        maintenanceCompletionId
      }
    }
  }
}

